import loggingimport psycopg2import psycopg2.extrasfrom src.config import db_connection_paramslog = logging.getLogger(__name__)# curated.sales_order_lines column order (sql/init/01_warehouse_schema.sql), and where# each value comes from in the DataFrame produced by src.transform.curated.build_curated.# city -> customer_city and category_name -> category because the table has no columns# for the extra customer/product detail that build_curated also keeps for analytics.TABLE_COLUMNS = [    'order_id', 'customer_id', 'product_id', 'order_timestamp', 'customer_city',    'customer_tier', 'product_name', 'category', 'brand', 'quantity', 'unit_price',    'discount_pct', 'gross_amount', 'discount_amount', 'net_amount', 'status',    'source_updated_at', 'pipeline_run_id', 'processed_at_utc', 'record_hash',]_RENAME = {'city': 'customer_city', 'category_name': 'category'}INSERT_COLUMNS_SQL = ', '.join(TABLE_COLUMNS)_UPDATE_COLUMNS = [c for c in TABLE_COLUMNS if c != 'order_id']_UPDATE_SET_SQL = ', '.join(f'{c} = EXCLUDED.{c}' for c in _UPDATE_COLUMNS)# Skip the write entirely when the incoming business content did not change: cheaper# than always overwriting, and it means updated_count in the return value is meaningful.UPSERT_SQL = f"""    INSERT INTO curated.sales_order_lines ({INSERT_COLUMNS_SQL})    VALUES %s    ON CONFLICT (order_id) DO UPDATE SET {_UPDATE_SET_SQL}    WHERE curated.sales_order_lines.record_hash <> EXCLUDED.record_hash"""def _rows_for_table(df):    frame = df.rename(columns=_RENAME)    missing = [c for c in TABLE_COLUMNS if c not in frame.columns]    if missing:        raise KeyError(f'curated data is missing column(s) required by the table: {missing}')    frame = frame[TABLE_COLUMNS]    return [tuple(row) for row in frame.itertuples(index=False, name=None)]def upsert_curated(df, run_id: str) -> int:    """Load curated.sales_order_lines using rerun-safe UPSERT semantics.    Requirement: order_id is the conflict key. A rerun with unchanged records    must not create duplicate business keys.    Returns the number of rows actually written (inserted or changed); rows whose    record_hash is unchanged are skipped by the WHERE clause in UPSERT_SQL and are    not counted, so running this twice on identical data returns 0 the second time.    """    if df.empty:        log.info('upsert_curated run_id=%s: nothing to load (empty curated set)', run_id)        return 0    rows = _rows_for_table(df)    conn = psycopg2.connect(**db_connection_params())    try:        with conn, conn.cursor() as cur:            psycopg2.extras.execute_values(                cur, UPSERT_SQL, rows, page_size=1000, fetch=False            )            # rowcount after INSERT ... ON CONFLICT ... WHERE counts only rows that            # were actually inserted or updated; WHERE-skipped rows are excluded.            affected = cur.rowcount            cur.execute('SELECT count(*) FROM curated.sales_order_lines')            total = cur.fetchone()[0]        log.info('upsert_curated run_id=%s: %d row(s) submitted, %d actually written, table now has %d row(s)',                 run_id, len(rows), affected, total)        return affected    finally:        conn.close()def load_partition(df, year: int, month: int, run_id: str) -> int:    """Load only a selected year/month partition and record audit.partition_loads.    df is expected to already be filtered to the requested partition (e.g. read from    data/partitioned/order_year=<year>/order_month=<month>/ in src.benchmark). Reruns    of the same partition are safe: sales_order_lines dedupes via upsert_curated, and    ON CONFLICT (partition_key) here overwrites the audit row instead of duplicating it.    """    written = upsert_curated(df, run_id)    partition_key = f'{year:04d}-{month:02d}'    conn = psycopg2.connect(**db_connection_params())    try:        with conn, conn.cursor() as cur:            cur.execute(                """                INSERT INTO audit.partition_loads                    (partition_key, loaded_at_utc, row_count, pipeline_run_id)                VALUES (%s, now(), %s, %s)                ON CONFLICT (partition_key) DO UPDATE SET                    loaded_at_utc = EXCLUDED.loaded_at_utc,                    row_count = EXCLUDED.row_count,                    pipeline_run_id = EXCLUDED.pipeline_run_id                """,                (partition_key, len(df), run_id),            )        log.info('load_partition %s run_id=%s: %d row(s) in partition, %d written',                 partition_key, run_id, len(df), written)        return written    finally:        conn.close()